source(file.path(dirname(sub("^--file=", "", commandArgs(FALSE)[grepl("^--file=", commandArgs(FALSE))])), "revision_common.R"))
z<-unique(read_csv(file.path(revision_dir,"audit/execution/raw_field_inventory.csv"))[,.(table,column,storage_type)])
z[,`:=`(revision_use="excluded unless documented below",interpretation="Not used in revised analytical inputs; retained unchanged in source staging",validation="No claim of field-level accuracy for unused columns")]
define<-function(tab,fields,meaning,check,use="core input") {
 z[table%in%tab & column%in%fields,`:=`(revision_use=use,interpretation=meaning,validation=check)]
}
define(z$table,"match_id","Opaque DAFT match identifier; preserves source identity. Date prefix is not used instead of date fields.","Unique within each table's declared composite key; do not merge competitions on match_id alone")
define(z$table,"teams","Own-side ordinal, 1 or 2. In bowling, this is the bowling side, not the batting side.","All values 1/2; joins to own-side match-team lookup; opponent=3-teams")
define(c("teams","batting","batting_noshow"),"innings","Innings number within the batting side, not absolute match-innings number.","Unique team-innings key; summed batting score and outs reconciled")
define("bowling","innings","Opponent batting side's innings number. Join to teams=3-bowling.teams to identify the batting innings.","Bowler wicket totals reconciled to opposing batting dismissals")
define("teams",c("team","competition"),"Source side/competition label; county Other bilateral in 1994-99 retained only after independent 915-match register reconciliation.","Unique match-team lookup; independent county register; modern Cricsheet linkage")
define("teams",c("start_date","end_date"),"Exact inclusive match dates. Cutoff is start_date <= 2025-12-31. Future predictors may update only after end_date.","Date parse, missingness and start <= end checked exhaustively")
define("teams",c("season_start_year","season_end_year"),"Season labels; distinct from calendar year and exact dates.","Retained as labels; dates govern sequencing")
define("teams","wicketkeeper","Nominated scorecard wicketkeeper identity; not a complete measure of every in-match keeping substitution.","Own-team identity checked; use as nominated keeper only")
define("teams",c("runs","wickets"),"Official team-innings totals, including team extras for runs.","Batting runs plus named extras; outs; all-out row completeness; residual gaps quarantined")
define("teams",c("wides","noballs","byes","legbyes","penalties"),"Run components of team extras; not numbers of deliveries.","Additive innings accounting; never fill an unexplained gap by inventing extras")
define("teams",c("team_batted","declared"),"Source indicators used to distinguish played innings, unused innings slots, declarations and possible forfeitures.","Cross-tabulated against absent batting rows; unusual played-zero records remain queries","audit only")
define("players","player","DAFT name-plus-birthdate key. This is not a guaranteed unique person: registry collision checks are required.","Local line-up unique; independent registry collision/split audit; unresolved keys quarantined")
define("players","position","Nominal listed XI position. Not actual batting-innings order.","Retained only for legacy sensitivity","sensitivity input")
define("players",c("birth_date","death_date"),"Source biographical dates, not verified solely by matching the embedded name key; death 9999-12-31 is unknown.","Age plausibility checked; targeted external errors repaired; wider metadata pilot still required","provisional metadata")
define("players",c("rh_bat","lh_bat","rh_bowl","lh_bowl"),"Binary handedness flags; all-zero is unknown and conflicting flags remain conflicting.","No implicit right-handed default; source validation still incomplete","provisional metadata")
define("players",c("fast","fast_medium","medium_fast","medium","slow_medium","seam","off_break","leg_break","googly","lob"),"Recorded career-style flags. Pace/spin both positive means mixed; neither means unknown. Lob retained without silently assigning pace. Not delivery-level style.","Explicit overrides for independently verified repertoire; no fabricated match-level delivery labels","provisional metadata")
define("batting","player","Numeric actual batting position for this innings. Exclude DNB entries. Replacement batting position can exceed eleven.","Independent code-path mode pilot; mode tie nearest median then lower position")
define("batting","batter","Batter identity, subject to the same collision caveat as players.player.","Unique match/team/innings/batter; own-line-up join; external source pilot")
define("batting",c("score","out"),"Batter runs and dismissal indicator. A real zero-not-out innings counts as an innings. Do not infer its absence from zero runs.","Conservation; team accounting; missing not-out and replacement checks; 63-match Cricsheet pilot")
define("batting",c("bowler","howout","fielder"),"Dismissal attribution. Run outs and other non-bowler dismissals are not credited to a bowler.","Dismissal-credit reconciliation; specific attribution errors corrected from independent scorecards","audit only")
define("batting","ballsfaced","Recorded balls faced, historically incomplete; zero is not universally established as an observed zero.","Coverage flag accompanies sums; not used to supply missing exposure","auxiliary only")
define("bowling","player","Numeric ordering on bowling card, not batter position or identity.","Never used to assign a batting role","excluded")
define("bowling","bowler","Bowler identity, subject to source identity collisions.","Unique match/team/innings/bowler; own-line-up join; independent registry audit")
define("bowling",c("overs","extraballs","balls_per_over"),"Whole scorecard overs, residual balls in partial over, and historical over length. Scorecard balls = overs*balls_per_over+extraballs. extraballs is NOT wides/no-balls.","Historical lengths preserved; Cricsheet miscounted overs explain seven pilot differences. Internal legacy legal_balls column is scorecard-derived; scorecard_balls is explicit alias.")
define("bowling",c("runs","wickets"),"Runs charged to bowler and bowler-credited wickets, distinct from team runs/wickets.","Conservation; dismissal credits; independent scorecards and Cricsheet pilot")
define("batting_noshow",c("player","batter","how"),"Separate non-batting/absent records; numeric listed slot, identity and reason. These are not zero-run batting innings.","Keep outside innings and modal batting-position denominators; use to inspect all-out completeness","audit only")
fwrite(z,file.path(revision_dir,"config/field_dictionary.csv"))
cat(nrow(z),"distinct source fields documented, with unused fields explicitly excluded.\n")
